/**
 * §15 task-set tests.
 *
 * Every fixture under test is SYNTHETIC — generated by `eval/fixtures/` and
 * never derived from a real transcript. No network: nothing here calls a model,
 * because nothing here needs one. A task set is data, and what has to be true
 * of it is checkable offline.
 *
 * What these tests are actually protecting, in the order the suite runs them:
 *
 *  - a malformed task must fail the SUITE, not a run six hours into a benchmark;
 *  - a task whose fixture does not produce the branch the task depends on is
 *    silently unmeasurable, so every fixture is ingested and its phase sequence
 *    asserted;
 *  - a checker that cannot fail is the worst defect a benchmark can have, so
 *    every one of the 30 is run against a right answer AND a wrong one;
 *  - fixtures must be byte-stable across generations, or D8's "L1 is a function
 *    of L0 + L2" is not testable at all.
 */
import { afterEach, describe, expect, it } from 'vitest';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { basename, join } from 'node:path';
import {
  ingest,
  openTaskStore,
  resolveConfig,
  segment,
  type PhaseType,
  type TaskStore,
  type TreeNode,
} from '@context-tree/core';
import {
  TASK_KINDS,
  TRAP_KINDS,
  materializeTrace,
  resolveChecker,
  taskEvents,
  validateTask,
  type CheckerInput,
  type CheckerToolCall,
  type EvalTask,
  type TaskEvent,
} from '../harness/task-spec.js';
import { loadRubric } from '../harness/judge.js';
import { FIXTURES_DIR, SHAPES, fixtureFiles, scenarioById } from '../fixtures/index.js';
import { TASKS, TASKS_PER_GROUP, assertGroupCounts, tasksOfKind, tasksWithTrap } from './index.js';
import { TASKS_DIR, taskFileContents } from './generate.js';
import { TASK_FILES, unusedScenarios } from './definitions.js';
import { exportedSymbols } from './checkers/grade.js';

const temps: string[] = [];
const handles: TaskStore[] = [];

afterEach(() => {
  while (handles.length > 0) handles.pop()?.close();
  while (temps.length > 0) rmSync(temps.pop() ?? '', { recursive: true, force: true });
});

function ingested(events: readonly TaskEvent[], overrides: Record<string, unknown> = {}): TaskStore {
  const root = mkdtempSync(join(tmpdir(), 'ct-tasks-'));
  temps.push(root);
  const handle = openTaskStore(resolveConfig({ root, ...overrides }));
  handles.push(handle);
  materializeTrace(events, handle);
  ingest({ handle });
  return handle;
}

function phaseSequence(handle: TaskStore): PhaseType[] {
  return handle.store
    .nodesInCreationOrder()
    .filter((node: TreeNode) => node.kind === 'phase')
    .map((node: TreeNode) => node.phase_type ?? 'other');
}

function fileNodePaths(handle: TaskStore): string[] {
  return handle.store.byKind('file').map((node: TreeNode) => String(node.meta_json.path ?? node.title));
}

const byId = (task: EvalTask): [string, EvalTask] => [task.id, task];

// ── the set itself ─────────────────────────────────────────────────────────

describe('§15 task set shape', () => {
  it.each(TASKS.map(byId))(
    '%s validates against the harness task-spec, so one malformed task fails this suite',
    (_id, task) => {
      // Re-validating the loaded task closes the loop `loadTasks` opens: it
      // throws on a bad file, but a reader cannot tell from a green suite
      // whether that path was ever exercised on THIS task.
      const result = validateTask({ ...task, baseDir: undefined });
      expect(result.errors).toEqual([]);
      expect(result.ok).toBe(true);
    },
  );

  it('holds exactly 10 fresh / 10 resumed / 10 adversarial — §15 asks for 30 in three groups', () => {
    expect(TASKS).toHaveLength(TASKS_PER_GROUP * TASK_KINDS.length);
    for (const kind of TASK_KINDS) expect(tasksOfKind(kind)).toHaveLength(TASKS_PER_GROUP);
  });

  it('fails loud when a group is the wrong size, rather than reporting a benchmark on 28 tasks', () => {
    expect(() => {
      assertGroupCounts(TASKS.slice(1));
    }).toThrow(/adversarial: 9/);
  });

  it('gives every task a unique id and a distinct fixture, so no two runs grade the same trace', () => {
    expect(new Set(TASKS.map((task) => task.id)).size).toBe(TASKS.length);
    expect(new Set(TASKS.map((task) => task.trace.fixture)).size).toBe(TASKS.length);
  });

  it('uses every scenario in the catalogue — an unused fixture is a trace nothing grades', () => {
    expect(unusedScenarios()).toEqual([]);
  });

  it('declares a trap on every adversarial task and on no other, and covers all three §15 traps', () => {
    for (const task of tasksOfKind('adversarial')) expect(task.trap).toBeDefined();
    for (const kind of ['fresh', 'resumed'] as const) {
      for (const task of tasksOfKind(kind)) expect(task.trap).toBeUndefined();
    }
    for (const trap of TRAP_KINDS) expect(tasksWithTrap(trap).length).toBeGreaterThan(0);
    expect(tasksWithTrap('stale-summary')).toHaveLength(4);
    expect(tasksWithTrap('contradiction')).toHaveLength(3);
    expect(tasksWithTrap('fetch-not-needed')).toHaveLength(3);
  });

  it('backs every trap with the field that makes it assertable, so no trap is decoration', () => {
    for (const task of tasksWithTrap('stale-summary')) {
      expect(task.expect.staleMarkers?.length ?? 0).toBeGreaterThan(0);
    }
    for (const task of tasksWithTrap('contradiction')) {
      expect(task.expect.answerContains?.length ?? 0).toBeGreaterThan(0);
    }
    for (const task of tasksWithTrap('fetch-not-needed')) {
      expect(task.expect.maxToolCalls).toBeDefined();
    }
  });

  it('never asserts requiresTool: only arm D has tools, so a tool requirement would gift D the §15 gap', () => {
    for (const task of TASKS) expect(task.expect.requiresTool).toBeUndefined();
  });

  it('turns every resumed task on a fact that is absent from its own prompt', () => {
    // An `answerContains` the prompt already supplies asserts nothing: the model
    // can pass by echoing. This is the check that keeps the resumed group honest.
    for (const task of tasksOfKind('resumed')) {
      const needles = task.expect.answerContains ?? [];
      expect(needles.length).toBeGreaterThan(0);
      for (const needle of needles) expect(task.prompt).not.toContain(needle);
    }
  });
});

// ── fixtures ingest into the tree each task assumes ────────────────────────

describe('every task fixture produces the tree its task depends on', () => {
  it.each(TASKS.map(byId))('%s ingests to the phase sequence its scenario declares', (id, task) => {
    const scenario = scenarioById(id);
    const handle = ingested(taskEvents(task));
    // Exact, not "contains": a task that reasons about "the third branch" is
    // wrong the moment an extra phase appears, and §7's neutral-phase rule
    // makes that a live risk whenever a fixture gains a shell command.
    expect(phaseSequence(handle)).toEqual(scenario.phases);
    expect(handle.store.root()).not.toBeNull();
  });

  it.each([...tasksOfKind('resumed'), ...tasksOfKind('adversarial')].map(byId))(
    '%s recorded every file its golden state names, so the state the checker grades is reachable',
    (_id, task) => {
      const events = taskEvents(task);
      const handle = ingested(events);
      const paths = fileNodePaths(handle);
      for (const file of task.golden) {
        // Edited -> a file node under its phase; read-only -> a recorded
        // `tool_call` on that path. The second case is real: the three
        // `fetch-not-needed` traps deliberately never edit anything, because
        // their whole point is that the answer is already in front of the agent.
        const touched =
          paths.includes(file.path) ||
          events.some((event) => event.type === 'tool_call' && event.path === file.path);
        expect(touched, `${task.id}: the session never touched ${file.path}`).toBe(true);
      }
    },
  );

  it('leaves fresh tasks out of that rule on purpose — their golden is a target, not a recorded state', () => {
    const task = tasksOfKind('fresh')[0];
    expect(task).toBeDefined();
    const handle = ingested(taskEvents(task as EvalTask));
    expect(fileNodePaths(handle)).toEqual([]);
  });

  it('keeps every resumed task’s buried fact out of its active branch, or the task measures nothing', () => {
    for (const task of tasksOfKind('resumed')) {
      const events = taskEvents(task);
      const handle = ingested(events);
      const phases = handle.store.nodesInCreationOrder().filter((node) => node.kind === 'phase');
      const active = phases.at(-1);
      expect(active).toBeDefined();
      const activeText = handle.trace
        .all()
        .filter((event) => {
          const start = active?.span_start_seq ?? 0;
          const end = active?.span_end_seq ?? 0;
          return event.seq >= start && event.seq <= end;
        })
        .map((event) => ('blob' in event && typeof event.blob === 'string' ? handle.blobs.getText(event.blob) : ''))
        .join('\n');
      for (const needle of task.expect.answerContains ?? []) {
        expect(activeText, `${task.id}: "${needle}" is in the active branch`).not.toContain(needle);
      }
    }
  });
});

// ── checkers ───────────────────────────────────────────────────────────────

/**
 * The answer a correct resumption produces, derived from the task rather than
 * hand-written: the golden files it had to end at, one symbol that really
 * exists in each, and the facts the task declares. Deriving it is the point —
 * a hand-written "good answer" would test the author's phrasing.
 */
function goldenAnswer(task: EvalTask): string {
  const parts: string[] = [];
  for (const file of task.golden) {
    parts.push(basename(file.path));
    const first = exportedSymbols(file.content)[0];
    if (first !== undefined) parts.push(first);
  }
  parts.push(...(task.expect.answerContains ?? []));
  return `Resuming this task: ${parts.join(', ')}.`;
}

/** An answer that recovered nothing. Contains no identifier any task requires. */
const EMPTY_ANSWER = 'There is not enough in front of me to say; someone should look at it.';

function inputFor(task: EvalTask, finalText: string, toolCalls: CheckerToolCall[] = []): CheckerInput {
  return { task, finalText, toolCalls, steps: 1, stoppedBy: 'stop' };
}

const WASTED_FETCHES: CheckerToolCall[] = [
  { name: 'context_search', args: { query: 'anything' }, ok: true },
  { name: 'context_fetch', args: { branch_id: 'n1' }, ok: true },
  { name: 'context_peek', args: { node_id: 'n1' }, ok: true },
];

describe('every checker passes its golden state and fails a wrong one', () => {
  it.each(TASKS.map(byId))('%s passes on the answer its golden state implies', async (_id, task) => {
    const checker = await resolveChecker(task);
    const result = await checker(inputFor(task, goldenAnswer(task)));
    expect(result.detail).toContain('met');
    expect(result.passed).toBe(true);
  });

  it.each(TASKS.map(byId))('%s fails on an answer that recovered nothing', async (_id, task) => {
    const checker = await resolveChecker(task);
    const result = await checker(inputFor(task, EMPTY_ANSWER));
    expect(result.passed).toBe(false);
    // A failure that does not name what failed is unreadable in results.json.
    expect(result.detail.length).toBeGreaterThan(20);
  });

  it.each(tasksWithTrap('fetch-not-needed').map(byId))(
    '%s fails a right answer that paid for retrieval it did not need (§18 over-fetching)',
    async (_id, task) => {
      const checker = await resolveChecker(task);
      const result = await checker(inputFor(task, goldenAnswer(task), WASTED_FETCHES));
      expect(result.passed).toBe(false);
      expect(result.detail).toMatch(/cap|forbids/);
    },
  );

  it.each(tasksWithTrap('stale-summary').map(byId))(
    '%s reports a stale-summary incident but does not fail an answer that merely mentions the old state',
    async (_id, task) => {
      const checker = await resolveChecker(task);
      const marker = (task.expect.staleMarkers ?? [])[0] as string;
      const mentioned = await checker(inputFor(task, `${goldenAnswer(task)} (${marker} was replaced.)`));
      expect(mentioned.staleSummaryIncident).toBe(true);
      expect(mentioned.passed).toBe(true);

      const followed = await checker(inputFor(task, `Working on ${marker} as described.`));
      expect(followed.staleSummaryIncident).toBe(true);
      expect(followed.passed).toBe(false);
    },
  );

  it('reports staleSummaryIncident only where the trap exists, so the metric is never a false zero', async () => {
    for (const task of [...tasksOfKind('fresh'), ...tasksWithTrap('contradiction')]) {
      const checker = await resolveChecker(task);
      const result = await checker(inputFor(task, goldenAnswer(task)));
      expect(result.staleSummaryIncident).toBeUndefined();
    }
  });

  it('says in the result which criteria a contradiction task hands to the judge', async () => {
    const task = tasksWithTrap('contradiction')[0] as EvalTask;
    const checker = await resolveChecker(task);
    const result = await checker(inputFor(task, goldenAnswer(task)));
    expect(result.detail).toContain('judged by rubric');
  });
});

// ── determinism (D1/D8) ────────────────────────────────────────────────────

describe('generated artifacts are byte-stable', () => {
  it('regenerates every fixture trace byte-identically — D1 requires bit-identical output', () => {
    const first = fixtureFiles();
    const second = fixtureFiles();
    expect(second).toEqual(first);
  });

  it('matches the committed fixture bytes, so a forgotten regeneration fails here', () => {
    for (const file of fixtureFiles()) {
      const onDisk = readFileSync(join(FIXTURES_DIR, file.name), 'utf8');
      expect(onDisk, `${file.name} is stale — regenerate with eval/tasks/generate.ts --write`).toBe(file.content);
    }
  });

  it('matches the committed task JSON, so golden states cannot drift from their traces', () => {
    const generated = taskFileContents();
    expect(generated).toEqual(taskFileContents());
    expect(generated).toHaveLength(TASK_FILES.length);
    for (const file of generated) {
      const onDisk = readFileSync(join(TASKS_DIR, file.name), 'utf8');
      expect(onDisk, `${file.name} is stale — regenerate with eval/tasks/generate.ts --write`).toBe(file.content);
    }
  });

  it('declares every fixture synthetic in the file itself, where it will outlive this README', () => {
    for (const file of fixtureFiles()) {
      expect(file.content.startsWith('// SYNTHETIC FIXTURE')).toBe(true);
    }
  });
});

// ── the rubric §15 names ───────────────────────────────────────────────────

describe('eval/rubric.md', () => {
  it('parses with the harness judge and carries the four criteria §15 grades on', () => {
    // §15 puts the rubric at exactly this path and `run.ts` defaults to it. A
    // rubric the judge cannot parse degrades a run to checkers-only silently,
    // which is the failure this test exists to make loud.
    const rubric = loadRubric(join(TASKS_DIR, '..', 'rubric.md'));
    expect(rubric.criteria.map((criterion) => criterion.id)).toEqual([
      'task-success',
      'state-recovery',
      'retrieval-discipline',
      'golden-state-fidelity',
    ]);
    // Concrete anchors for every score, or two judges do not agree.
    for (const criterion of rubric.criteria) {
      for (const score of [0, 1, 2, 3, 4, 5]) {
        expect(criterion.description, `${criterion.id} has no anchor for ${String(score)}`).toContain(
          `**${String(score)}**`,
        );
      }
    }
  });
});

// ── segmenter shapes ───────────────────────────────────────────────────────

function shape(id: string): TaskEvent[] {
  const found = SHAPES.find((fixture) => fixture.id === id);
  if (found === undefined) throw new Error(`no shape ${id}`);
  return found.events;
}

describe('the fixture catalogue covers the shapes §7 has to handle', () => {
  it('segments a clean progression into one phase per activity kind', () => {
    expect(phaseSequence(ingested(shape('shape-clean-progression')))).toEqual([
      'diagnosis',
      'implementation',
      'verification',
      'delivery',
    ]);
  });

  it('keeps a read- and shell-dominated session as ONE branch — the case that motivated neutral phases', () => {
    const events = shape('shape-read-dominated');
    expect(phaseSequence(ingested(events))).toEqual(['diagnosis']);
    // The counterfactual is the whole argument for Ruling C6: with `other`
    // non-neutral, the same session shatters into single-event phases and the
    // tree stops being worth assembling.
    expect(phaseSequence(ingested(events, { neutralPhases: [] })).length).toBeGreaterThan(5);
  });

  it('gives one path two file nodes when it is re-edited in a later phase (§7 file nodes are phase-scoped)', () => {
    const handle = ingested(shape('shape-reedit-across-phases'));
    const paths = fileNodePaths(handle);
    expect(paths.filter((path) => path === 'src/net/backoff.ts')).toHaveLength(2);
  });

  it('honours an explicit segment_boundary over the tool state machine', () => {
    expect(phaseSequence(ingested(shape('shape-explicit-boundary')))).toEqual(['diagnosis', 'review']);
  });

  it('routes an unmapped tool name to `other` and reports it, never crashing (§18)', () => {
    const root = mkdtempSync(join(tmpdir(), 'ct-tasks-'));
    temps.push(root);
    const handle = openTaskStore(resolveConfig({ root }));
    handles.push(handle);
    materializeTrace(shape('shape-unmapped-tool'), handle);
    const result = ingest({ handle });
    expect(result.stats.unmappedTools).toContain('frobnicate_widget');
    expect(phaseSequence(handle)).toEqual(['other']);
  });

  it('still ingests a syntactically broken edit — §12/D9 error tolerance is why tree-sitter is here', () => {
    const root = mkdtempSync(join(tmpdir(), 'ct-tasks-'));
    temps.push(root);
    const handle = openTaskStore(resolveConfig({ root }));
    handles.push(handle);
    materializeTrace(shape('shape-broken-edit'), handle);
    const result = ingest({ handle });
    expect(fileNodePaths(handle)).toContain('src/pricing/line.ts');
    // Spans OR a degraded fallback: which one depends on whether the grammar is
    // installed, and §12 requires the file node either way. Zero of both would
    // mean the broken file produced nothing at all, which is the failure.
    expect(result.stats.spans + result.stats.degradedFiles).toBeGreaterThan(0);
  });

  it('segments the 400+ event fixture inside §16 M1’s 5 ms budget', () => {
    const events = shape('shape-long-session');
    expect(events.length).toBeGreaterThanOrEqual(400);
    const handle = ingested(events);
    const config = handle.config;
    const stored = handle.trace.all();

    // Best of five: §7's budget is for the pass itself, and a single cold
    // measurement mostly reports JIT warm-up. A regression to O(n^2) shows up
    // in the best run just as clearly as in the mean.
    let best = Number.POSITIVE_INFINITY;
    for (let i = 0; i < 5; i += 1) {
      const started = performance.now();
      const result = segment(stored, {
        toolPhase: config.toolPhase,
        neutralPhases: config.neutralPhases,
        fileTools: config.fileTools,
        taskTitle: config.taskTitle,
      });
      best = Math.min(best, performance.now() - started);
      expect(result.stats.events).toBe(stored.length);
    }
    expect(best).toBeLessThan(5);
  });
});
